fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // We only consider up to n participants or fewer if participations has fewer elements.
    let limit = n.min(participations.len() as u8) as usize;

    // Count how many participants are eligible:
    // eligibility: (5 - attendance_count) >= k
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count() as u8;

    // Number of teams is integer division of eligible participants by 3.
    eligible_count / 3
}